(349733, 27724, 9854, '<td valign="top">Dying unknown is levels more tragic than the war that caused it. Sad, but poignantly touches the challenge. It is a picture of riddles burried under stone markers that could easily stand in as question marks.</td>', 'Dying unknown is levels more tragic than the war that caused it. Sad, but poignantly touches the challenge. It is a picture of riddles burried under stone markers that could easily stand in as question marks.', '2003-07-07 23:55:07.000000', NULL, 1),
(349735, 27660, 9854, '<td valign="top">Is that a door to an early childhood centre, or a Bohemian cafe?  The way it was shot makes it look like a perspective of a child  just coming out of kiddie class. Nice.</td>', 'Is that a door to an early childhood centre, or a Bohemian cafe?  The way it was shot makes it look like a perspective of a child  just coming out of kiddie class. Nice.', '2003-07-08 00:00:26.000000', NULL, 1),
(349745, 27657, 9854, '<td valign="top">nice rag rocking colors</td>', 'nice rag rocking colors', '2003-07-08 00:11:22.000000', NULL, 1),
(349775, 27667, 6600, '<td valign="top">Very nice composition and focus throughout.  The orientation works well here.  Fits challenge nicely.  Good job!</td>', 'Very nice composition and focus throughout.  The orientation works well here.  Fits challenge nicely.  Good job!', '2003-07-08 01:01:54.000000', NULL, 1),
(349776, 27726, 6600, '<td valign="top">Pretty funny.... Nicely done photo, fits challenge well.  Nice job!</td>', 'Pretty funny.... Nicely done photo, fits challenge well.  Nice job!', '2003-07-08 01:03:41.000000', NULL, 1),
(349780, 27349, 6600, '<td valign="top">All to real of a scene...  great job setting this up (ground level view makes the photo).  Great job!</td>', 'All to real of a scene...  great job setting this up (ground level view makes the photo).  Great job!', '2003-07-08 01:06:26.000000', NULL, 1),
(349790, 27466, 6600, '<td valign="top">Very nice grayscale ''portrait'' type shot.  Each subject seems to convey a different thought or mood.  Neat!  (I like the jovial mood from the one on the right - certainly appears to be in her happly place during this shot)</td>', 'Very nice grayscale ''portrait'' type shot.  Each subject seems to convey a different thought or mood.  Neat!  (I like the jovial mood from the one on the right - certainly appears to be in her happly place during this shot)', '2003-07-08 01:20:36.000000', NULL, 1),
