(351698, 27655, 7086, '<td valign="top">Image seems quite soft, not really anything to grab my attention</td>', 'Image seems quite soft, not really anything to grab my attention', '2003-07-09 19:12:47.000000', NULL, 1),
(351700, 27684, 7086, '<td valign="top">I''m intrigued by the lolly lying in the road.</td>', 'I''m intrigued by the lolly lying in the road.', '2003-07-09 19:15:25.000000', NULL, 1),
(351701, 27261, 7086, '<td valign="top">Shame they are in the shadow I can''t really make out any details.</td>', 'Shame they are in the shadow I can''t really make out any details.', '2003-07-09 19:16:30.000000', NULL, 1),
(351703, 27688, 7086, '<td valign="top">A lot of wasted space at the top and the bird is slightly out of focus.</td>', 'A lot of wasted space at the top and the bird is slightly out of focus.', '2003-07-09 19:17:29.000000', NULL, 1),
(351706, 27397, 7086, '<td valign="top">Very well lit and captured, not a great fan of cropped portraits though.</td>', 'Very well lit and captured, not a great fan of cropped portraits though.', '2003-07-09 19:19:14.000000', NULL, 1),
(351708, 27623, 7086, '<td valign="top">Living in Brighton I have my own conspiracy theory on this one. Not too sure about the sepia effect but I like that you''ve blended the sea into the sky.</td>', 'Living in Brighton I have my own conspiracy theory on this one. Not too sure about the sepia effect but I like that you''ve blended the sea into the sky.', '2003-07-09 19:22:12.000000', NULL, 1),
(351710, 27565, 7086, '<td valign="top">I like the humour, it''s well captured and I''m sure you''ve had more than a few comments!</td>', 'I like the humour, it''s well captured and I''m sure you''ve had more than a few comments!', '2003-07-09 19:23:25.000000', NULL, 1),
(351714, 27667, 7086, '<td valign="top">Assuming this is a staged shot it negates the need to ask any questions. Good viewpoint and lighting.</td>', 'Assuming this is a staged shot it negates the need to ask any questions. Good viewpoint and lighting.', '2003-07-09 19:26:33.000000', NULL, 1),
(351715, 27659, 7086, '<td valign="top">Powerful image, well captured. Phonelines leading into the face are slightly distracting IMO.</td>', 'Powerful image, well captured. Phonelines leading into the face are slightly distracting IMO.', '2003-07-09 19:27:57.000000', NULL, 1),
(351719, 27285, 7086, '<td valign="top">Works well as a concept, unfortunately only a fraction of the image is focused and, apart from the paper, lacks detail due to the lighting.</td>', 'Works well as a concept, unfortunately only a fraction of the image is focused and, apart from the paper, lacks detail due to the lighting.', '2003-07-09 19:31:30.000000', NULL, 1),
(351727, 27170, 7086, '<td valign="top">Good humourous shot with well captured detail.</td>', 'Good humourous shot with well captured detail.', '2003-07-09 19:34:57.000000', NULL, 1),
(351732, 27612, 7086, '<td valign="top">Surely an encyclopedia is better for answering questions? Well captured shot though.</td>', 'Surely an encyclopedia is better for answering questions? Well captured shot though.', '2003-07-09 19:39:00.000000', NULL, 1),
(351735, 27609, 7086, '<td valign="top">Image is soft, noisy and over-exposed.</td>', 'Image is soft, noisy and over-exposed.', '2003-07-09 19:40:09.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(351742, 27349, 7086, '<td valign="top">Compelling photo, alot of noise but judging from the lighting hard to avaoid.</td>', 'Compelling photo, alot of noise but judging from the lighting hard to avaoid.', '2003-07-09 19:42:16.000000', NULL, 1),
(351745, 27388, 7086, '<td valign="top">I would have considered taking this photo at a different time of day, the postion of the sun makes it too flat.</td>', 'I would have considered taking this photo at a different time of day, the postion of the sun makes it too flat.', '2003-07-09 19:43:36.000000', NULL, 1),
(351747, 27651, 7086, '<td valign="top">Graffiti :{&gt;</td>', 'Graffiti :{>', '2003-07-09 19:44:29.000000', NULL, 1),
(351768, 27565, 6527, '<td valign="top">Uh....<br/>I''m confused.<br/>I think the unanswered questions here is: What are you thinking?</td>', 'Uh....I''m confused.I think the unanswered questions here is: What are you thinking?', '2003-07-09 19:50:36.000000', NULL, 1),
(351872, 27689, 9385, '<td valign="top">Beautiful photo, it doesn''t seem to leave any question unanswered</td>', 'Beautiful photo, it doesn''t seem to leave any question unanswered', '2003-07-09 21:48:33.000000', NULL, 1),
(351880, 27285, 9385, '<td valign="top">Excellent idea, something just seems to be  off with the lighting, my eye is drawn to the bright spot and details are missed.</td>', 'Excellent idea, something just seems to be  off with the lighting, my eye is drawn to the bright spot and details are missed.', '2003-07-09 22:01:15.000000', NULL, 1),
(351908, 27678, 10047, '<td valign="top">Cute capture. Good use of lighting, and well focused. Were fireworks providing the lighting and the concern on his face?</td>', 'Cute capture. Good use of lighting, and well focused. Were fireworks providing the lighting and the concern on his face?', '2003-07-09 22:39:47.000000', NULL, 1),
(351956, 27522, 2079, '<td valign="top">Great detail and expression. Nice utilization of the rule of thirds. The very bright orange of the life vest is just a bit over saturated for my taste; its pulling my eye away from the face of this perfect subject. The reflection in the water adds an artistic touch and the over-all theme meets the challenge well. <br/>Great work. 9<br/></td>', 'Great detail and expression. Nice utilization of the rule of thirds. The very bright orange of the life vest is just a bit over saturated for my taste; its pulling my eye away from the face of this perfect subject. The reflection in the water adds an artistic touch and the over-all theme meets the challenge well. Great work. 9', '2003-07-09 23:29:23.000000', NULL, 1),
(352006, 27718, 10045, '<td valign="top">This is a really great image.  Reminds me of all the magic of being a kid.</td>', 'This is a really great image.  Reminds me of all the magic of being a kid.', '2003-07-10 00:28:50.000000', NULL, 1),
(352013, 27347, 10045, '<td valign="top">I think the answer to this one is obvious... :)</td>', 'I think the answer to this one is obvious... :)', '2003-07-10 00:31:04.000000', NULL, 1),
(352028, 27726, 6325, '<td valign="top">OK, I want to know what is going on under there. Good tones.</td>', 'OK, I want to know what is going on under there. Good tones.', '2003-07-10 00:44:08.000000', NULL, 1),
(352034, 27533, 7033, '<td valign="top">Lighting is perhaps what I like best about the shot.  And it definitely meets the challenge... I''m certainly wondering exactly what the heck it is!</td>', 'Lighting is perhaps what I like best about the shot.  And it definitely meets the challenge... I''m certainly wondering exactly what the heck it is!', '2003-07-10 00:48:40.000000', NULL, 1),
(352039, 27627, 7033, '<td valign="top">Black / white adds a great deal of visual interest to this shot by forcing the focus to the textures and patterns.  Very well shot!  (And what exactly are ''sea beans''?)</td>', 'Black / white adds a great deal of visual interest to this shot by forcing the focus to the textures and patterns.  Very well shot!  (And what exactly are ''sea beans''?)', '2003-07-10 00:52:14.000000', NULL, 1),
(352042, 27694, 6870, '<td valign="top">Oh yea! Looks like a mad scientist to me!</td>', 'Oh yea! Looks like a mad scientist to me!', '2003-07-10 00:54:26.000000', NULL, 1),
(352043, 27632, 7033, '<td valign="top">Nice, visually interesting shot.  Overall composition works very well; only problem in my opinion is the slight glare off the table at the top center of the frame.</td>', 'Nice, visually interesting shot.  Overall composition works very well; only problem in my opinion is the slight glare off the table at the top center of the frame.', '2003-07-10 00:55:04.000000', NULL, 1),
(352047, 27096, 6870, '<td valign="top">Three things that I always thought went with each other. At least they appear quite natural in this photo! Nice work! Lighting is a bit ordinary for an extraordinary idea, but then, maybe that''s the point. Still, it might be fun to experiment with light levels and unusual points of view to build mood. On the other hand, I like the ordinariness of it! Gorsh, I can''t make up my mind, so I''ll just give you 9 and move on! Keep up the good work.</td>', 'Three things that I always thought went with each other. At least they appear quite natural in this photo! Nice work! Lighting is a bit ordinary for an extraordinary idea, but then, maybe that''s the point. Still, it might be fun to experiment with light levels and unusual points of view to build mood. On the other hand, I like the ordinariness of it! Gorsh, I can''t make up my mind, so I''ll just give you 9 and move on! Keep up the good work.', '2003-07-10 00:56:47.000000', NULL, 1),
(352048, 27707, 6870, '<td valign="top">Wonderfully evocative! Macro and point of view work well here, as does DOF. 9</td>', 'Wonderfully evocative! Macro and point of view work well here, as does DOF. 9', '2003-07-10 00:57:22.000000', NULL, 1),
(352052, 27724, 7033, '<td valign="top">Well done... a very poignant image!  I think the subdued tone of the headstones in the background emphasizes the overall mood, and I wish the front headstone were similarly exposed.  A slightly different (higher) angle might also have allowed a crop that eliminated the slightly distracting stones at the top of the frame.  Overall, though, a fantastic image that meets the challenge well.  --9</td>', 'Well done... a very poignant image!  I think the subdued tone of the headstones in the background emphasizes the overall mood, and I wish the front headstone were similarly exposed.  A slightly different (higher) angle might also have allowed a crop that eliminated the slightly distracting stones at the top of the frame.  Overall, though, a fantastic image that meets the challenge well.  --9', '2003-07-10 00:59:36.000000', NULL, 1),
(352056, 27267, 6870, '<td valign="top">Lovely idea and wonderful composition! Light is a little harsh, but this photo works for me.</td>', 'Lovely idea and wonderful composition! Light is a little harsh, but this photo works for me.', '2003-07-10 01:00:48.000000', NULL, 1),
(352057, 27586, 6870, '<td valign="top">Poor Buddha! A nicely composed photo with the head and shoulders at the thirds. Colors seem overprocessed, which I don''t mind very much, except that in this case, it doesn''t enhace the photo''s feel or mood or communication.</td>', 'Poor Buddha! A nicely composed photo with the head and shoulders at the thirds. Colors seem overprocessed, which I don''t mind very much, except that in this case, it doesn''t enhace the photo''s feel or mood or communication.', '2003-07-10 01:02:32.000000', NULL, 1),
