(354188, 27374, 8860, '<td valign="top">Nice capture of... a sparkler? Crisp and some lovely shapes created. Could it have looked better slightly off-centre though? 7</td>', 'Nice capture of... a sparkler? Crisp and some lovely shapes created. Could it have looked better slightly off-centre though? 7', '2003-07-11 20:22:02.000000', NULL, 1),
