INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(354271, 27700, 1379, '<td valign="top">The textures in this photo make me reach out to stroke the computer screen! Incredible.  Awesome composition.</td>', 'The textures in this photo make me reach out to stroke the computer screen! Incredible.  Awesome composition.', '2003-07-11 22:04:46.000000', NULL, 1),
(354273, 27664, 1379, '<td valign="top">The aw-shucksy feel of your photo, combined with your title, are making me laugh so much!!  I can''t wait to add this to my favorites! It''s just over-the-top absurd to me.  I love it!  I really would love to know the person that drives that car.  Hilarious!!</td>', 'The aw-shucksy feel of your photo, combined with your title, are making me laugh so much!!  I can''t wait to add this to my favorites! It''s just over-the-top absurd to me.  I love it!  I really would love to know the person that drives that car.  Hilarious!!', '2003-07-11 22:07:07.000000', NULL, 1),
(354276, 27617, 1379, '<td valign="top">I really hate to shout, but what an EXCELLENT UNANSWERED QUESTION!!!   Thanks for making a statement with your entry.</td>', 'I really hate to shout, but what an EXCELLENT UNANSWERED QUESTION!!!   Thanks for making a statement with your entry.', '2003-07-11 22:09:25.000000', NULL, 1),
(354306, 27608, 10111, '<td valign="top">this is a fantasic image.  I can''t think of anything that could have been done differently</td>', 'this is a fantasic image.  I can''t think of anything that could have been done differently', '2003-07-11 23:08:57.000000', NULL, 1),
(354308, 27620, 10111, '<td valign="top">Nice Title for the image</td>', 'Nice Title for the image', '2003-07-11 23:09:20.000000', NULL, 1),
(354327, 27356, 5983, '<td valign="top">I enjoy this photo a lot.  The contrast between the light and dark really make this photo what it is.  Good job.</td>', 'I enjoy this photo a lot.  The contrast between the light and dark really make this photo what it is.  Good job.', '2003-07-11 23:20:56.000000', NULL, 1),
(354366, 27619, 2612, '<td valign="top">I am really curious to find out how that was done. Blue tone really sets the mood and the highlights on the liquid really draw the attention. I wish I had suggestions to offer, but it looks great just as it is.</td>', 'I am really curious to find out how that was done. Blue tone really sets the mood and the highlights on the liquid really draw the attention. I wish I had suggestions to offer, but it looks great just as it is.', '2003-07-12 00:54:40.000000', NULL, 1),
(354367, 27722, 2612, '<td valign="top">Really interesting shot. I find the reflection and shadow in the lower right corner a little distracting, but it is very minor and I had to work hard to even find that suggestion.</td>', 'Really interesting shot. I find the reflection and shadow in the lower right corner a little distracting, but it is very minor and I had to work hard to even find that suggestion.', '2003-07-12 01:00:47.000000', NULL, 1),
(354372, 27490, 2612, '<td valign="top">the mystery surrounding abandon buildings has always fascinated me, I wish I would have thought of using it for this challenge. I like the photo, but the white sky seems a little harsh. Blue sky or storm clouds might have helped with that, but I know they don''t alway cooperate with you time frame for taking making a photo.</td>', 'the mystery surrounding abandon buildings has always fascinated me, I wish I would have thought of using it for this challenge. I like the photo, but the white sky seems a little harsh. Blue sky or storm clouds might have helped with that, but I know they don''t alway cooperate with you time frame for taking making a photo.', '2003-07-12 01:07:14.000000', NULL, 1),
(354376, 27619, 6870, '<td valign="top">I''m less interested in the spot editing than I am in what this is and what is going on and why a glass is tipping, etc. Anyway, super shot. By the book! 10</td>', 'I''m less interested in the spot editing than I am in what this is and what is going on and why a glass is tipping, etc. Anyway, super shot. By the book! 10', '2003-07-12 01:10:21.000000', NULL, 1),
(354378, 27388, 6870, '<td valign="top">Stately, grand and formal, as it should be. Lighting is a bit harsh and bright, but this is a super shot.</td>', 'Stately, grand and formal, as it should be. Lighting is a bit harsh and bright, but this is a super shot.', '2003-07-12 01:11:02.000000', NULL, 1),
(354380, 27466, 6870, '<td valign="top">Three of these gals are checking him out, but only one is daydreaming about  him! Super work! 9</td>', 'Three of these gals are checking him out, but only one is daydreaming about  him! Super work! 9', '2003-07-12 01:11:40.000000', NULL, 1),
(354381, 27724, 6870, '<td valign="top">Wonderful composition, super lighting and engaging photograph. 9</td>', 'Wonderful composition, super lighting and engaging photograph. 9', '2003-07-12 01:12:11.000000', NULL, 1),
(354387, 27522, 2612, '<td valign="top">I like the strong contrast between the life vest and the water. The other technical elements, such as where the subject sits in the frame and the focus are all good. I think a look of panic or concern would have stirred me to worry more about the unanswered question, but it is still a good photo.</td>', 'I like the strong contrast between the life vest and the water. The other technical elements, such as where the subject sits in the frame and the focus are all good. I think a look of panic or concern would have stirred me to worry more about the unanswered question, but it is still a good photo.', '2003-07-12 01:17:21.000000', NULL, 1),
(354393, 27672, 2612, '<td valign="top">I have to complement you on the raw shock value of this shot. I was going to comment on the upper right being out of focus.... but the focus, highlights, and stong diagonal line all help to to put my attention right on the jagged edge. I don''t know that I would hang it on the wall, but it''s a very affective photograph.</td>', 'I have to complement you on the raw shock value of this shot. I was going to comment on the upper right being out of focus.... but the focus, highlights, and stong diagonal line all help to to put my attention right on the jagged edge. I don''t know that I would hang it on the wall, but it''s a very affective photograph.', '2003-07-12 01:22:23.000000', NULL, 1),
(354398, 27660, 2612, '<td valign="top">Is the guard picking his nose? I like the bright colors of the door, but I find myself looking for a central subject or some relationship between the door and the guard. Maybe you could use some technique, such as rule of thirds or a leading line, to draw me into the subject.</td>', 'Is the guard picking his nose? I like the bright colors of the door, but I find myself looking for a central subject or some relationship between the door and the guard. Maybe you could use some technique, such as rule of thirds or a leading line, to draw me into the subject.', '2003-07-12 01:27:45.000000', NULL, 1),
(354408, 27632, 9833, '<td valign="top">Great idea ! Definitley makes you wonder.</td>', 'Great idea ! Definitley makes you wonder.', '2003-07-12 01:40:43.000000', NULL, 1),
(354452, 27672, 10132, '<td valign="top">What...is it?  So...nice...</td>', 'What...is it?  So...nice...', '2003-07-12 03:40:03.000000', NULL, 1),
(354453, 27721, 10132, '<td valign="top">Wow!</td>', 'Wow!', '2003-07-12 03:41:11.000000', NULL, 1),
(354586, 27612, 6458, '<td valign="top">Where are the missing letters?<br/> <br/>Good one.. I like the composition.</td>', 'Where are the missing letters? Good one.. I like the composition.', '2003-07-12 13:31:58.000000', NULL, 1),
(354588, 27619, 6458, '<td valign="top">I know, I know!   <br/> <br/>It''s magic, isn''t it?  Great shot, tones, and focus.</td>', 'I know, I know!    It''s magic, isn''t it?  Great shot, tones, and focus.', '2003-07-12 13:35:30.000000', NULL, 1),
(354590, 27267, 6458, '<td valign="top">This is just good. It nails the challenge topic but isn''t an easy photo to ''get''. If you take the time to look, the realization of how bad this must have been hits you. What happened to this family? Was it disease? What about the parents? <br/> <br/>Good shot. 10.</td>', 'This is just good. It nails the challenge topic but isn''t an easy photo to ''get''. If you take the time to look, the realization of how bad this must have been hits you. What happened to this family? Was it disease? What about the parents?  Good shot. 10.', '2003-07-12 13:40:24.000000', NULL, 1),
(354643, 27588, 6870, '<td valign="top">Nothing like an explosion to get attention! Nice work, especially the lighting and composition. 9</td>', 'Nothing like an explosion to get attention! Nice work, especially the lighting and composition. 9', '2003-07-12 14:39:30.000000', NULL, 1),
(354644, 27497, 6870, '<td valign="top">The superb lighitng and composition here realy do make me wonder what these are. You capture such wonderfully intriguing patterns in this photo! 10</td>', 'The superb lighitng and composition here realy do make me wonder what these are. You capture such wonderfully intriguing patterns in this photo! 10', '2003-07-12 14:40:21.000000', NULL, 1),
(354645, 27267, 7711, '<td valign="top">I wonder what happened in 1881. WOW, all those kids. Very good interpretation of the challenge. The light is a bit too bright on the bottom of the marker, while the rest of it is in shadow. If you caught this during sundown, the light might have been very flattering, and complementary to the emotive nature of your subject.</td>', 'I wonder what happened in 1881. WOW, all those kids. Very good interpretation of the challenge. The light is a bit too bright on the bottom of the marker, while the rest of it is in shadow. If you caught this during sundown, the light might have been very flattering, and complementary to the emotive nature of your subject.', '2003-07-12 14:40:33.000000', NULL, 1),
(354646, 27611, 6870, '<td valign="top">Nice idea, and the composition is verynice as we can see a variety of things this firewood once was.</td>', 'Nice idea, and the composition is verynice as we can see a variety of things this firewood once was.', '2003-07-12 14:41:08.000000', NULL, 1),
(354647, 27535, 6870, '<td valign="top">Good question! And  your composition works to invite thought beyond the space, and sets this scene in a larger world. 9</td>', 'Good question! And  your composition works to invite thought beyond the space, and sets this scene in a larger world. 9', '2003-07-12 14:42:01.000000', NULL, 1),
(354652, 27659, 7711, '<td valign="top">now there is an unanswered question! Very neat idea, I like the accent of the rain on the poster too, and the faraway expression on her face. The tight composition keeps our attention on the question too. well done.</td>', 'now there is an unanswered question! Very neat idea, I like the accent of the rain on the poster too, and the faraway expression on her face. The tight composition keeps our attention on the question too. well done.', '2003-07-12 14:43:13.000000', NULL, 1),
(354653, 27718, 6870, '<td valign="top">Very nice, intimate shot. Point of view is wonderful. The only nitpicky thing that I could mention is the right wrist, which seems to have just a tad too much light. Nice work. 9</td>', 'Very nice, intimate shot. Point of view is wonderful. The only nitpicky thing that I could mention is the right wrist, which seems to have just a tad too much light. Nice work. 9', '2003-07-12 14:43:21.000000', NULL, 1),
(354656, 27577, 6870, '<td valign="top">Fun colors and lines make this photo work for me. The chairs do compete just a bit, though with the shutters. Nice work!</td>', 'Fun colors and lines make this photo work for me. The chairs do compete just a bit, though with the shutters. Nice work!', '2003-07-12 14:44:24.000000', NULL, 1),
(354657, 27356, 6870, '<td valign="top">Amazing how a simple scene can have such impact! I like the naturalness of this shot a lot! B/W is a good choice and adds an interpretive element.</td>', 'Amazing how a simple scene can have such impact! I like the naturalness of this shot a lot! B/W is a good choice and adds an interpretive element.', '2003-07-12 14:45:39.000000', NULL, 1),
(354658, 27584, 6870, '<td valign="top">A high quality macro shot. Lighting is marvelous to add a sense of nostalgia and mystery to the image.</td>', 'A high quality macro shot. Lighting is marvelous to add a sense of nostalgia and mystery to the image.', '2003-07-12 14:46:27.000000', NULL, 1),
(354659, 27679, 6870, '<td valign="top">Wonderful point of view and DOF. Stately, formal and wonderful image!</td>', 'Wonderful point of view and DOF. Stately, formal and wonderful image!', '2003-07-12 14:47:03.000000', NULL, 1),
(354662, 27682, 6870, '<td valign="top">I like this shot a lot! The various shapes and lines really mix well here. Bold choice to crop so low and put the flower so high, but I like how this choice adds an interpretive element to the photo. 9</td>', 'I like this shot a lot! The various shapes and lines really mix well here. Bold choice to crop so low and put the flower so high, but I like how this choice adds an interpretive element to the photo. 9', '2003-07-12 14:48:31.000000', NULL, 1),
(354699, 27374, 4517, '<td valign="top">A sparkler. 9</td>', 'A sparkler. 9', '2003-07-12 15:31:00.000000', NULL, 1),
(354701, 27349, 9262, '<td valign="top">I like the grainieness//noise. I think it adds to the whole atmosphere of this image. It reminds me a lot of a scene from CSI. This is a creative take on the challenge. <br/> <br/>Critical comments : tthe crop is a little tight on the left and the bright lights draw your eye like a moth to a bug light.</td>', 'I like the grainieness//noise. I think it adds to the whole atmosphere of this image. It reminds me a lot of a scene from CSI. This is a creative take on the challenge.  Critical comments : tthe crop is a little tight on the left and the bright lights draw your eye like a moth to a bug light.', '2003-07-12 15:35:00.000000', NULL, 1),
(354702, 27654, 9262, '<td valign="top">meets the challenge? Yes<br/>Technical Aspects: good lighting, focus, composition. <br/>Creative/Artistic : This meets the challenge very well, I want to know what he is looking for, what is he doing, where is he? etc. but I think this shot lacks emotional impact. Your subject looks rather bored.</td>', 'meets the challenge? YesTechnical Aspects: good lighting, focus, composition. Creative/Artistic : This meets the challenge very well, I want to know what he is looking for, what is he doing, where is he? etc. but I think this shot lacks emotional impact. Your subject looks rather bored.', '2003-07-12 15:37:43.000000', NULL, 1),
(354707, 27386, 9262, '<td valign="top">Meets the challenge? Yes<br/>Technical : I really like how one of your subjects is engaging the camera. It makes me feel like we shouldn''t be listening to the conversation, hence the need for whispering. Focus, lighting, composition good. <br/>Artistic/Creative : I like the choice of b&amp;W. I think it serves as a good contrast to the subject matter of gossip. Gossip is not very black &amp; white at all, it is very subjective.</td>', 'Meets the challenge? YesTechnical : I really like how one of your subjects is engaging the camera. It makes me feel like we shouldn''t be listening to the conversation, hence the need for whispering. Focus, lighting, composition good. Artistic/Creative : I like the choice of b&W. I think it serves as a good contrast to the subject matter of gossip. Gossip is not very black & white at all, it is very subjective.', '2003-07-12 15:43:14.000000', NULL, 1),
(354737, 27655, 9262, '<td valign="top">Meets the Challenge? : Yes<br/>Technical : Lighting is harsh. Composition is ok, dof is good. leading lines of steps fairly interesting. <br/>Creative : It does make me ask Where do the steps go but there is little emotional impact in this image to make me want to look at it more.</td>', 'Meets the Challenge? : YesTechnical : Lighting is harsh. Composition is ok, dof is good. leading lines of steps fairly interesting. Creative : It does make me ask Where do the steps go but there is little emotional impact in this image to make me want to look at it more.', '2003-07-12 16:44:31.000000', NULL, 1),
(354738, 27669, 9262, '<td valign="top">Meets the Challenge? Not really, your title is making the viewer want to know more about your image, not the image itself. <br/>Technical : the soft focus is nice for a young child. i like the use of side lighting as well. it creates interesting shadows on your subjects face.<br/>Creative/Artistic : I don''t really feel anything when viewing this image other than aww what a cute kid.</td>', 'Meets the Challenge? Not really, your title is making the viewer want to know more about your image, not the image itself. Technical : the soft focus is nice for a young child. i like the use of side lighting as well. it creates interesting shadows on your subjects face.Creative/Artistic : I don''t really feel anything when viewing this image other than aww what a cute kid.', '2003-07-12 16:47:38.000000', NULL, 1),
(354739, 27690, 9262, '<td valign="top">Meets the Challenge? Not really, your subject is holding a snake up in front of a house. The only question that I can think of is it a wild snake or a domesticated snake?<br/>Technical : This is the best part of your image. The composition is fairly interesting with the angles of the house and the sinous lines of the snake. <br/>Creative/Artistic: If someone was afraid of snakes, this may have some impact on them.</td>', 'Meets the Challenge? Not really, your subject is holding a snake up in front of a house. The only question that I can think of is it a wild snake or a domesticated snake?Technical : This is the best part of your image. The composition is fairly interesting with the angles of the house and the sinous lines of the snake. Creative/Artistic: If someone was afraid of snakes, this may have some impact on them.', '2003-07-12 16:51:16.000000', NULL, 1),
(354740, 27580, 9262, '<td valign="top">Squirrels are a common animal subject. Your composition is technically ok and only mildly interesting. I feel the weakest part of your entry is in meeting the challenge. Your title is what makes this viewer want to know more, not the image itself.</td>', 'Squirrels are a common animal subject. Your composition is technically ok and only mildly interesting. I feel the weakest part of your entry is in meeting the challenge. Your title is what makes this viewer want to know more, not the image itself.', '2003-07-12 16:54:16.000000', NULL, 1),
(354741, 27584, 9262, '<td valign="top">What are these keys for? Or why are there so many? To be honest, they are just a bunch of keys. I think your composition is the stongest part of this image. Technically, it is Ok but it doesn''t do anything for me in the artistic/creative bit.</td>', 'What are these keys for? Or why are there so many? To be honest, they are just a bunch of keys. I think your composition is the stongest part of this image. Technically, it is Ok but it doesn''t do anything for me in the artistic/creative bit.', '2003-07-12 16:57:26.000000', NULL, 1),
(354772, 27667, 5728, '<td valign="top">Very well composed. B&amp;W works well. This pic tells me a whole story, only the question "why"? remains unanswered. One of my favourites for the challenge - 10.</td>', 'Very well composed. B&W works well. This pic tells me a whole story, only the question "why"? remains unanswered. One of my favourites for the challenge - 10.', '2003-07-12 18:42:12.000000', NULL, 1),
(354773, 27386, 5728, '<td valign="top">Very focused and detailed, well done. But what the heck is she saying??? - 10.</td>', 'Very focused and detailed, well done. But what the heck is she saying??? - 10.', '2003-07-12 18:42:33.000000', NULL, 1),
(354774, 27694, 5728, '<td valign="top">This is a wonderful and humorous portrait. I wouldn''t have cropped the hair all out at the top of the image though - 9.</td>', 'This is a wonderful and humorous portrait. I wouldn''t have cropped the hair all out at the top of the image though - 9.', '2003-07-12 18:45:38.000000', NULL, 1),
(354775, 27726, 5728, '<td valign="top">Very funny photo! Actually looking at this pic a couple of questions jump to mind, so you''ve met the challenge at least twofold for me, well done - 9.</td>', 'Very funny photo! Actually looking at this pic a couple of questions jump to mind, so you''ve met the challenge at least twofold for me, well done - 9.', '2003-07-12 18:45:57.000000', NULL, 1),
(354776, 27588, 5728, '<td valign="top">The things DPC''ers do just for a good photo :-) Okay I''ll ask, what is it? Did ya blow up the neighbours house? Or is this your idea of a good barbecue? The rich colors are so vibrant, your photo has really come alive. Just the two little black marks in the sky are a little bothersome, but without spot editing them there isn''t much you can do about it - 9.</td>', 'The things DPC''ers do just for a good photo :-) Okay I''ll ask, what is it? Did ya blow up the neighbours house? Or is this your idea of a good barbecue? The rich colors are so vibrant, your photo has really come alive. Just the two little black marks in the sky are a little bothersome, but without spot editing them there isn''t much you can do about it - 9.', '2003-07-12 18:46:24.000000', NULL, 1),
(354792, 27361, 6870, '<td valign="top">Cute child! I love the lighting on his face against the dark background. I''m trying to figure out how this fits in the challenge, though. From the title, I guess that he did something wrong? But I don''t see any evidence of this.</td>', 'Cute child! I love the lighting on his face against the dark background. I''m trying to figure out how this fits in the challenge, though. From the title, I guess that he did something wrong? But I don''t see any evidence of this.', '2003-07-12 19:12:45.000000', NULL, 1),
(354793, 27627, 6870, '<td valign="top">This is such a wonderful, intriguing photo. I have no idea what these are, so I suppose it meets the challenge! Lighting is so nice.</td>', 'This is such a wonderful, intriguing photo. I have no idea what these are, so I suppose it meets the challenge! Lighting is so nice.', '2003-07-12 19:13:29.000000', NULL, 1),
(354796, 27609, 6870, '<td valign="top">She is a bit out of focus, but I enjoy how the lighter background frames her without making her totally dark.</td>', 'She is a bit out of focus, but I enjoy how the lighter background frames her without making her totally dark.', '2003-07-12 19:14:09.000000', NULL, 1),
(354800, 27688, 6870, '<td valign="top">I didn''t know cat birds ate cat food! Nice pun here. I love the diagonal lines in the background; they add interest and just a touch of drama and don''t let the image get boring. Bird seems slightly out of focus.</td>', 'I didn''t know cat birds ate cat food! Nice pun here. I love the diagonal lines in the background; they add interest and just a touch of drama and don''t let the image get boring. Bird seems slightly out of focus.', '2003-07-12 19:15:45.000000', NULL, 1),
(354801, 27347, 6870, '<td valign="top">Why is he standing here like this? Where are his clothes? Why such great lighting? Unanswered questions, I guess!</td>', 'Why is he standing here like this? Where are his clothes? Why such great lighting? Unanswered questions, I guess!', '2003-07-12 19:16:52.000000', NULL, 1),
(354804, 27289, 6870, '<td valign="top">I like the contrast of the drama and emotion of the dead bird with the random everyday items behind. It gives this image a sense of meaninglessness. Nice work.</td>', 'I like the contrast of the drama and emotion of the dead bird with the random everyday items behind. It gives this image a sense of meaninglessness. Nice work.', '2003-07-12 19:17:59.000000', NULL, 1),
(354806, 27374, 6870, '<td valign="top">Nice capture of the sparkler! The question isn''t that profound or significant, but it certainly is a question! Nice.</td>', 'Nice capture of the sparkler! The question isn''t that profound or significant, but it certainly is a question! Nice.', '2003-07-12 19:18:58.000000', NULL, 1),
(354809, 27705, 6870, '<td valign="top">I like the composition here, and the background makes this very interesting. I''m a little confused as to what my next thoughts should be--it may be just a little TOO ambiguous.</td>', 'I like the composition here, and the background makes this very interesting. I''m a little confused as to what my next thoughts should be--it may be just a little TOO ambiguous.', '2003-07-12 19:19:27.000000', NULL, 1),
(354810, 27683, 6870, '<td valign="top">This photo does indeed make me wonder what kind of predator this is!  Nice composition and shadows. Light may be a little harsh and bright; perhaps darker light would add even more mystery and danger to this shot.</td>', 'This photo does indeed make me wonder what kind of predator this is!  Nice composition and shadows. Light may be a little harsh and bright; perhaps darker light would add even more mystery and danger to this shot.', '2003-07-12 19:21:01.000000', NULL, 1),
(354813, 27626, 6870, '<td valign="top">Nice journalistic shot. The abundance of grain works well for demonstrating a grungy reality, but it is SO abundant that it looks added.</td>', 'Nice journalistic shot. The abundance of grain works well for demonstrating a grungy reality, but it is SO abundant that it looks added.', '2003-07-12 19:21:54.000000', NULL, 1),
(354815, 27689, 6870, '<td valign="top">Or twelve firecrackers! Fun drama here! Nice diagonal lines, and I like the close crop. Does not inspire deep thought, but certainly a well done photo.</td>', 'Or twelve firecrackers! Fun drama here! Nice diagonal lines, and I like the close crop. Does not inspire deep thought, but certainly a well done photo.', '2003-07-12 19:22:57.000000', NULL, 1),
(354816, 27669, 6870, '<td valign="top">Nice soft focus works for me. Close crop is nice, too. I''m not sure how to connect the image with the title, so it may be just a tad too ambiguous. Nice lighting, too.</td>', 'Nice soft focus works for me. Close crop is nice, too. I''m not sure how to connect the image with the title, so it may be just a tad too ambiguous. Nice lighting, too.', '2003-07-12 19:24:00.000000', NULL, 1),
(354819, 27248, 6870, '<td valign="top">I think the drama of this well composed photograph upstages any unanswered questions it may infer; I just want to look at the guy doing his bike stunt.</td>', 'I think the drama of this well composed photograph upstages any unanswered questions it may infer; I just want to look at the guy doing his bike stunt.', '2003-07-12 19:25:08.000000', NULL, 1),
(354821, 27619, 4285, '<td valign="top">Call me stupid........but what I want to know is, how you did it? That''s the main question it leaves me asking. The blue combined with the translucence of the glass and the liquid is pure magic. The only element that distracts from the image is the line behind the glass. 8</td>', 'Call me stupid........but what I want to know is, how you did it? That''s the main question it leaves me asking. The blue combined with the translucence of the glass and the liquid is pure magic. The only element that distracts from the image is the line behind the glass. 8', '2003-07-12 19:26:33.000000', NULL, 1),
(354822, 27310, 6870, '<td valign="top">The light in the shadows is great here! In the sun, it may be a bit bright. You might try experimenting with dropping the levels to make the whole image darker, which might add more mystery as well as keep areas from being burned.</td>', 'The light in the shadows is great here! In the sun, it may be a bit bright. You might try experimenting with dropping the levels to make the whole image darker, which might add more mystery as well as keep areas from being burned.', '2003-07-12 19:26:41.000000', NULL, 1),
(354853, 27361, 4285, '<td valign="top">I was looking through some of the user profiles today and I came across this picture. At the time I didn''t make the connection but I knew it looked familiar. When I started doing some comments it hit me but I couldn''t remember who you were to let you know it was visible for all to see. Once you see this I''m sure you will remove it anyways. Cute kid.</td>', 'I was looking through some of the user profiles today and I came across this picture. At the time I didn''t make the connection but I knew it looked familiar. When I started doing some comments it hit me but I couldn''t remember who you were to let you know it was visible for all to see. Once you see this I''m sure you will remove it anyways. Cute kid.', '2003-07-12 20:28:06.000000', NULL, 1),
(354855, 27497, 7778, '<td valign="top">I believe they''re prayers...<br/> <br/>Not a ''great'' photograph, but an interesting and worthwhile capture, which, IMO, would gain interest with a much shallower dof (redundant info = background blurred, darkened or otherwise rendered unobtrusive) to emphasize the subject.<br/> <br/>PS: no plural for ''stuff''.</td>', 'I believe they''re prayers... Not a ''great'' photograph, but an interesting and worthwhile capture, which, IMO, would gain interest with a much shallower dof (redundant info = background blurred, darkened or otherwise rendered unobtrusive) to emphasize the subject. PS: no plural for ''stuff''.', '2003-07-12 20:30:12.000000', NULL, 1),
(354898, 27619, 10151, '<td valign="top">My first geuss would have to be that the glass is underwater, upsidedown spilling air up? Great Shot!!</td>', 'My first geuss would have to be that the glass is underwater, upsidedown spilling air up? Great Shot!!', '2003-07-12 21:54:36.000000', NULL, 1),
