(355463, 27650, 2199, '<td valign="top">Those feet in the middle look VERY familiar....</td>', 'Those feet in the middle look VERY familiar....', '2003-07-13 23:55:30.000000', NULL, 1),
(355466, 27619, 9232, '<td valign="top">This left me with questions.  It was also a creative composition that was pleasing to see.<br/> <br/>Good job.</td>', 'This left me with questions.  It was also a creative composition that was pleasing to see. Good job.', '2003-07-13 23:59:38.000000', NULL, 1),
(355479, 27356, 200, '<td valign="top">This is my favorite of the challenge. I just love his expression. Nice work</td>', 'This is my favorite of the challenge. I just love his expression. Nice work', '2003-07-14 00:09:30.000000', NULL, 1),
