(355555, 27386, 5391, '<td valign="top">Didn''t get a chance to comment during the challenge, but I thought this was wonderful, not only for the fabulous tones and detail (you can see every strand of their hair, even...) but also for the feelings it provokes.  Really took me back to those old days of high school.  :)  I gave it a 9.  Fabulous.</td>', 'Didn''t get a chance to comment during the challenge, but I thought this was wonderful, not only for the fabulous tones and detail (you can see every strand of their hair, even...) but also for the feelings it provokes.  Really took me back to those old days of high school.  :)  I gave it a 9.  Fabulous.', '2003-07-14 01:20:54.000000', NULL, 0),
(355556, 27699, 8911, '<td valign="top">Thanks for the comments - I wasn''t sure whether to straighten the handle or the doorframe on this one.<br/> <br/>I''m afraid the bracelet and the door handle are both mine, though; this one was staged. (It raised some unanswered questions locally, too: my neighbors gave me the ''what is she doing, anyway?'' look.)</td>', 'Thanks for the comments - I wasn''t sure whether to straighten the handle or the doorframe on this one. I''m afraid the bracelet and the door handle are both mine, though; this one was staged. (It raised some unanswered questions locally, too: my neighbors gave me the ''what is she doing, anyway?'' look.)', '2003-07-14 01:22:48.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(355557, 27535, 5391, '<td valign="top">I was surprised at how many people thought this was edited...  I had to check my e-mail every day, waiting for the admins to ask me for the original so I didn''t get disqualified.  It never occurred to me that people wouldn''t look close enough to see the bricks painted black.  :)  Glad to hear that I really did leave some "unanswered questions"!</td>', 'I was surprised at how many people thought this was edited...  I had to check my e-mail every day, waiting for the admins to ask me for the original so I didn''t get disqualified.  It never occurred to me that people wouldn''t look close enough to see the bricks painted black.  :)  Glad to hear that I really did leave some "unanswered questions"!', '2003-07-14 01:23:19.000000', NULL, 0),
(355558, 27619, 1280, '<td valign="top">Great execution of this!  A very well deserved win.  <br/>Grayce</td>', 'Great execution of this!  A very well deserved win.  Grayce', '2003-07-14 01:24:52.000000', NULL, 0),
(355561, 27397, 200, '<td valign="top">Very nice work! :) I thought I could see a difference in image quality this time around...did you upload the new version already?</td>', 'Very nice work! :) I thought I could see a difference in image quality this time around...did you upload the new version already?', '2003-07-14 01:27:43.000000', NULL, 0),
(355563, 27386, 714, '<td valign="top">Way to go David!  Execellent portrait.</td>', 'Way to go David!  Execellent portrait.', '2003-07-14 01:28:11.000000', NULL, 0),
